namespace Ilmenyx.Core;

public static partial class HelpContent
{
    private static HelpLanguage En() => new("en",
        new Dictionary<string, string>
        {
            [HelpKeys.WelcomeWindow] = "Ilmenyx Controller — Welcome",
            [HelpKeys.WelcomeTitle] = "Welcome to Ilmenyx",
            [HelpKeys.WelcomeBody] = "Ilmenyx shows what's inside your PC, how it's doing right now, and helps you game better on Linux. Want a quick tour of the main screens?",
            [HelpKeys.WelcomeNote] = "The tour is optional. You can take it later from Help, at the end of the sidebar.",
            [HelpKeys.WelcomeStart] = "Take the tour (2 min)",
            [HelpKeys.WelcomeLater] = "Not now",
            [HelpKeys.TourName] = "ILMENYX TOUR",
            [HelpKeys.TourCounter] = "Step {0} of {1}",
            [HelpKeys.TourBack] = "Back",
            [HelpKeys.TourNext] = "Next",
            [HelpKeys.TourFinish] = "Finish",
            [HelpKeys.TourSkip] = "Skip tour",
            [HelpKeys.TourKeys] = "Enter: next · Esc: exit",
            [HelpKeys.TourAccessible] = "Ilmenyx tour, step {0} of {1}: {2}",
            [HelpKeys.HelpNav] = "Help",
            [HelpKeys.HelpTitle] = "Help Center",
            [HelpKeys.HelpSubtitle] = "What each page is for, how to use it in a few steps, and answers to the most common questions",
            [HelpKeys.HelpRetour] = "Retake the tour",
            [HelpKeys.HelpIndex] = "GO TO",
            [HelpKeys.HelpPurpose] = "WHAT IT'S FOR",
            [HelpKeys.HelpSteps] = "HOW TO USE",
            [HelpKeys.HelpFaq] = "FREQUENTLY ASKED QUESTIONS",
            [HelpKeys.HelpOpenPage] = "Open the page",
            [HelpKeys.HelpContext] = "Help for this page",
            [HelpKeys.HelpSearchPrefix] = "Help · ",
            [HelpKeys.HelpStepAccessible] = "Step {0}: {1}",
        },
        [
            new("start", "GETTING STARTED"), new("diag", "DIAGNOSTICS"), new("games", "GAMES"), new("perf", "PERFORMANCE"),
            new("maker", "MAKER"), new("tools", "TOOLS"),
        ],
        [
            S("help", "start", "First steps",
                "How to find your way around Ilmenyx: the menu, the search, the top buttons and where to find help.",
                [
                    "In the sidebar, pages are in groups (Diagnostics, Games, Performance, Maker and Tools). Click a group's name to open or close it.",
                    "In the search at the top, type part of a page's name or a question (e.g. temperature) and pick it from the list.",
                    "The round buttons at the top change the language and the theme (dark or light) and pause or resume the live readings.",
                    "The \"?\" button next to the title opens this help right at the part about the page you're on.",
                    "To see the tour again, click Retake the tour at the top of this page.",
                ],
                Q("privacy", "Does Ilmenyx send my data anywhere?", "There's no telemetry. The internet is only used when you click something that needs it, such as the Network test or the online lookups in Compatibility and Drivers."),
                Q("auto", "Does any heavy test run on its own?", "No. Benchmark, Stress test and the OC check only start after your click and a confirmation that says what will happen."),
                Q("password", "When does Ilmenyx ask for a password?", "Only for actions that change the system, such as unlocking the CPU sensors or installing the NVIDIA driver. The system's own window asks for it; Ilmenyx never sees the password.")),

            S("dash", "start", "Overview",
                "The first screen: a live summary of the PC, with the computer model, the CPU load and temperature, the GPU, the memory, the components and the last benchmark's score.",
                [
                    "Look at the big card at the top: the PC's name, the processor and the CPU, GPU and RAM readings right now.",
                    "In the Activity chart, choose what to see (Load, Temperature or Draw) and the period (1, 5 or 15 minutes).",
                    "Click a component (CPU, memory, disk…) to open the page with its details.",
                    "The PERFORMANCE card shows the last benchmark's score; Open Benchmark takes you to the test.",
                    "If the yellow \"Unlock CPU sensors\" button shows up in the sidebar, click it to see the CPU temperature and power.",
                ],
                Q("cputemp", "Why doesn't the CPU temperature show?", "Sometimes Linux doesn't load the sensor module or hides the reading from regular users. Click \"Unlock CPU sensors\" in the sidebar: the system asks for your password once and you can undo it with the same button. In a virtual machine the sensor may not exist."),
                Q("power", "Why is the Draw button grayed out?", "CPU power comes from a kernel counter (RAPL) that many distributions only let the administrator read. The \"Unlock CPU sensors\" button fixes that too. Some processors don't have this counter."),
                Q("dash", "What does \"—\" mean instead of a number?", "That this reading isn't available on this PC. It's not a sign of a defect: Ilmenyx prefers showing \"—\" to making up a value."),
                Q("monitor", "Do the live readings slow the PC down?", "No. On a laptop with an 11th-gen Core i5, Ilmenyx sitting idle uses about 3% of one of its 8 cores and 250 to 360 MB of memory. The pause button at the top stops the live readings.")),

            S("system", "diag", "System",
                "Lists the hardware and software found: system, motherboard, processor, memory, graphics card and storage.",
                [
                    "Choose a category in the list (Operating system, Motherboard, Processor, Memory, Graphics card or Storage).",
                    "In Storage, the rings show how full each disk is.",
                    "Click Refresh to read again, or export as JSON or an HTML report.",
                    "In Memory, Import RAM modules reads a saved dmidecode file to show each stick.",
                ],
                Q("ram", "Why don't the details of each RAM stick show?", "Linux only shows these details to the administrator. Run the dmidecode command shown on the page in the terminal, save the output to a file and use Import RAM modules. Ilmenyx doesn't run that command and doesn't show serial numbers.")),

            S("sensors", "diag", "Sensors",
                "All the temperatures, fans, voltages and power readings the kernel offers, as they come.",
                [
                    "Click Refresh sensors to read everything again.",
                    "Monitor (2 s) updates by itself every 2 seconds; Stop monitor ends it.",
                    "Show raw text displays the values as the kernel reports them, useful for technicians.",
                    "Export sensors JSON or HTML saves the readings to a file.",
                ],
                Q("dup", "Why do some sensors show up twice?", "Some chips are read by more than one kernel driver. Ilmenyx shows each source as it is, without adding up or hiding."),
                Q("hwmon", "What is hwmon?", "It's the part of Linux that gathers the sensors of the motherboard, CPU, GPU and disks. Ilmenyx only reads this data; it doesn't change anything.")),

            S("gpu", "diag", "GPU",
                "Full graphics card specifications and live sensors (usage, clock, temperature and memory) when the driver reports them.",
                [
                    "If there's more than one graphics card, choose with the buttons at the top.",
                    "The cards show manufacturer, model, memory, driver and features such as Vulkan and ray tracing.",
                    "The live part updates by itself while the page is open.",
                ],
                Q("nocounters", "Why doesn't the GPU show usage or temperature?", "Not every driver reports these counters (for example nouveau or some integrated GPUs). In that case the page says so instead of showing a made-up number."),
                Q("notice", "What does the notice about AMD and NVIDIA mean?", "That Ilmenyx hasn't been tested on every card yet: a dedicated AMD GPU wasn't tested and NVIDIA was validated only on a GeForce 940MX. The data comes from the driver, but double-check the results.")),

            S("disks", "diag", "Disks",
                "Health, wear and temperature of each disk, with a verdict: HEALTHY, WARNING, CRITICAL or NO DATA.",
                [
                    "Look at each disk's card and its verdict.",
                    "For more complete data, click Query SMART (read only) on the disk's card.",
                    "If you already have a saved smartctl report, import it in SMART · offline import.",
                    "Click Refresh to read again.",
                ],
                Q("verdict", "Is the disk verdict guaranteed?", "No. It's an estimate made from the disk's own data. Back up any disk with a warning, not only the critical ones."),
                Q("usb", "Why does the USB stick show NO DATA?", "USB sticks and some external HDDs don't report health to the system."),
                Q("smart", "What is SMART?", "It's the report the disk itself keeps about errors, hours of use and wear. Ilmenyx only reads it; it never writes to the disk or runs tests on it.")),

            S("energy", "diag", "Power",
                "Battery (charge, health and cycles), connected power source and draw read from the kernel's sensors.",
                [
                    "Open the page: it reads the battery and power source right away.",
                    "Click Refresh to read again.",
                    "On a desktop PC without a battery, only the power source and draw show up.",
                ],
                Q("psu", "Is the draw shown the one at the wall outlet?", "No. It's what the kernel's power sensors report (CPU, GPU…), not the PC's power supply (PSU)."),
                Q("cycles", "Why don't the battery's cycles or original capacity show?", "Some laptops don't report this data to Linux.")),

            S("net", "diag", "Network",
                "Shows network traffic and runs a test to find out whether lag comes from your PC, the Wi-Fi or the provider.",
                [
                    "The chart shows the traffic of the last 5 minutes.",
                    "Click Test and confirm. The test uses the internet and takes about 30 seconds.",
                    "Read the result: response time (ping), variation (jitter), loss and speed, with an explanation of where the problem is.",
                    "Cancel stops the test.",
                ],
                Q("data", "Does the network test use data?", "Yes, about 100 MB (more on very fast connections). That's why it only runs after you confirm."),
                Q("ping", "What are ping and jitter?", "Ping is the time a packet takes to go and come back. Jitter is how much that time varies; high jitter causes hiccups in online games.")),

            S("procs", "diag", "Processes",
                "The programs using the most CPU and memory right now, from the live monitor.",
                [
                    "The list updates by itself with each reading.",
                    "Click CPU or Memory, at the top of the table, to sort.",
                    "Pause the monitor at the top of the window to freeze the list.",
                ],
                Q("names", "Does Ilmenyx keep or send the list of programs?", "No. The names only show on this screen and are never exported.")),

            S("launcher", "games", "Games",
                "Gathers your games in one place and opens each one with a profile for more performance.",
                [
                    "Games from Steam, Heroic (Epic and GOG) and Lutris show up by themselves; Refresh list looks again.",
                    "For another game, click + Add executable and use Browse… to choose the file: a Linux program or a Windows .exe.",
                    "Choose the game and adjust the profile: dedicated GPU, MangoHud, GameMode, power profile and arguments. Profile for more FPS turns on the recommended options.",
                    "Click Play. For Steam games, the arguments only apply after Apply to Steam options.",
                    "Do you only have a Windows game's installer (setup.exe)? Click Install Windows game, choose the installer and the game's folder and follow the window's tips.",
                ],
                Q("winfirst", "Why does the Windows game take a while the first time?", ".exe games run with Proton (the layer that makes Windows games work on Linux), without needing Steam. The first time, Proton is downloaded (about 1 GB) and the game's folder is prepared, which takes a few minutes. After that it opens normally."),
                Q("wininstall", "How do I install a game from its Windows installer?", "On the Games page, click Install Windows game. Choose the installer (.exe) and the folder where the game will end up. When the installer asks where to install, use C:\\Jogos (already created): the game is installed inside the temporary Windows, as on a real Windows, and at the end Ilmenyx moves the finished game to your folder. Uncheck DirectX, .NET and Visual C++: Proton already takes care of them. The installer runs once in a disposable Windows, deleted at the end; then click Add next to the game found so it joins the list."),
                Q("guard", "What is the protection against fullscreen freezes?", "On laptops with two graphics cards (Intel + NVIDIA), some fullscreen Windows games can freeze the whole screen, and only restarting the PC brings it back. The profile's \"Protection against fullscreen freezes (vsync)\" option makes Proton sync frames with the monitor, which prevents the freeze. It comes on, only shows on these laptops and caps FPS at the screen's refresh rate; uncheck it if you want uncapped FPS."),
                Q("dgpu", "What is a dedicated GPU?", "Laptops with two graphics cards have an integrated one, which saves battery, and a dedicated, stronger one. The option makes the game use the dedicated one (PRIME offload). With a single GPU there's nothing to choose."),
                Q("mangohud", "What is MangoHud?", "An overlay that shows FPS, temperature and usage on top of the game. When you check the option in the game's profile, Ilmenyx creates its configuration by itself. If you play for at least 30 seconds with it on, the session's FPS shows up in FPS estimate as \"Measured on this PC\"."),
                Q("gamemode", "What is GameMode and why is the option grayed out?", "GameMode gives the game priority while it runs. The option is grayed out when the gamemoderun program isn't installed; install the gamemode package from your distribution."),
                Q("steamclose", "Why does Steam close when I apply the options?", "Steam rewrites its options when it exits; that's why it must be closed for Ilmenyx to save. A backup of the file is made before changing it."),
                Q("steamid", "What is the Steam ID for in a Windows game?", "It's optional. With the game's number on the store (store.steampowered.com/app/ID, or on the Compatibility page), Proton applies its known fixes for it."),
                Q("wayland", "What is \"Native Proton on Wayland (experimental)\"?", "Makes the Windows game open directly on Wayland, without going through XWayland (PROTON_ENABLE_WAYLAND=1 variable). It comes off and only applies when the session is Wayland and the game uses GE-Proton or UMU-Proton 10 or newer; Valve's official Proton doesn't document this option. Below the option it says whether it's in use or why it was left out. If the game opens with the wrong window, no cursor or no controller, uncheck it."),
                Q("lowlatency", "What is \"Low latency (experimental)\"?", "Enables NVIDIA Reflex for Windows games (PROTON_ENABLE_NVAPI=1, through DXVK-NVAPI). Then turn on the Reflex option in the game's menu. Only for NVIDIA cards with the proprietary driver; for AMD and Intel, Proton doesn't document an equivalent option, so nothing is turned on. The two experimental options never go together with options that conflict with them, using the same table as the Compatibility page.")),

            S("compat", "games", "Compatibility",
                "Tells whether a game runs well on Linux: ProtonDB rating, Steam Deck badge, anti-cheat and what worked for people with hardware like yours.",
                [
                    "Choose a game from your Steam or search by name or Steam ID.",
                    "Download report database brings other players' reports to the PC.",
                    "Look up online fetches the latest data, only when you click.",
                    "In Recommended combination, apply to Steam only the options that work together; Undo goes back to what it was.",
                    "Alternatives show the options that were left out and why (they conflict with another, don't suit your card or a program is missing).",
                ],
                Q("guarantee", "Does the rating guarantee the game will run?", "No. It counts other players' reports, sorted by hardware similarity: it's a starting point for testing, not a guarantee."),
                Q("combo", "Why do some options end up in Alternatives?", "Each report uses its own options, and some conflict with each other: PROTON_USE_WINED3D=1 swaps DXVK for OpenGL and cancels the DXVK_ and VKD3D_ options; -dx11 and -dx12 ask for different APIs; a variable holds only one value. Others only suit NVIDIA (NVAPI) or AMD (RADV_) cards, or need a program that isn't installed (such as mangohud). The recommended combination gathers the most used ones that work together on your PC."),
                Q("art", "Where does the game image come from?", "From your Steam, if the game is installed. If not, it's downloaded from Steam (shared.akamai.steamstatic.com) only after you accept Look up online, and it stays on the PC for 30 days."),
                Q("extras", "What about the experimental options in the game's profile?", "If the game's profile (Games page) has \"Native Proton on Wayland\" or \"Low latency\" on, the Recommended combination warns when one of its options conflicts with them, such as PROTON_HIDE_NVIDIA_GPU=1 or Gamescope."),
                Q("anticheat", "What is anti-cheat?", "It's the program some online games use against cheating. Some don't accept Linux, and then online mode may not open even if the game runs well.")),

            S("gamecheck", "games", "Game won't open?",
                "Checks, without changing anything, the most common reasons Steam, Proton, Flatpak or a game won't open: Ubuntu's AppArmor, user namespaces, SELinux, Arch's multilib, Fedora's RPM Fusion, Flathub, the Flatpak Steam's access to other disks, the Vulkan driver, 32-bit libraries and split-lock.",
                [
                    "The page checks by itself when it opens; Check checks again.",
                    "Items with PROBLEM or WARNING come first: read what was found, the explanation and the risk.",
                    "When the fix is only for your user (Flathub, the Flatpak Steam's access to a disk), a button does it with confirmation, and Undo reverts it.",
                    "The rest (anything that asks for a password or reduces security) shows the exact command: Copy and paste it into the terminal yourself.",
                ],
                Q("apparmorwhy", "Why doesn't Ilmenyx fix AppArmor by itself?", "Because the fix loosens a system protection. Ilmenyx explains, shows the command and the warning, and leaves the decision to you. If Steam and Flatpak open normally, don't change anything."),
                Q("steamdisk", "My Steam library on another disk disappeared. What do I do?", "If your Steam is a Flatpak, it only sees your home folder. Use Allow … for Steam in the \"Flatpak Steam: access to game disks\" item, then close and reopen Steam."),
                Q("maxmapwhere", "Where do I adjust vm.max_map_count?", "On the Optimize page, which shows the current value and the command. This page only points there.")),

            S("fps", "games", "FPS estimate",
                "Shows how many FPS (frames per second) to expect in each game on this PC, as a range with a confidence level.",
                [
                    "The first time, click Calibrate now (≈1 min): Ilmenyx measures the GPU with a short game scene and the CPU with a game simulation, and stops on its own if the PC reaches 90 °C. Before that, the numbers are gray and marked \"provisional\".",
                    "Scroll the page: when you reach Catalog games, the title and the search stay fixed at the top and only the game list scrolls. The round arrow in the bottom-right corner goes back to the top.",
                    "Read the range, the confidence (medium, low or very low) and each card's basis: this PC's benchmark, specifications or reference table.",
                    "Games opened from the Games page with MangoHud on show \"Measured on this PC\": the real FPS of your sessions. If you set the graphics quality you use in the game's profile, these sessions also adjust the estimate for the other games.",
                    "Choose resolution, quality and upscaling to redo the math. Everything is calculated on your PC: this page doesn't use the internet.",
                ],
                Q("calibrate", "What does calibration do and when should I redo it?", "It runs a game scene on the GPU for 15 seconds and a game simulation on one CPU thread for 10 seconds, and keeps the result on your PC. Ilmenyx asks you to calibrate again if you change the GPU, the CPU or the video driver version. Keep the laptop plugged in."),
                Q("range", "Why a range and not an exact number?", "Because it's an estimate calculated from your GPU's and CPU's measured (or tabulated) performance, not a measurement of the game. Scene, driver and settings change the result."),
                Q("personal", "What is \"your N measured sessions\" on the card?", "When there are sessions measured with MangoHud at the same chosen graphics quality, Ilmenyx compares the measured with the estimate and corrects the other games with the same bottleneck. With one session the correction is small; with three or more the confidence goes up one level."),
                Q("none", "Why does NO ESTIMATE show up?", "When the GPU or the CPU isn't in the table, has no known specifications and the PC hasn't been calibrated yet. Calibrating fixes it in most cases."),
                Q("real", "How do I see my PC's real FPS?", "Open the game from the Games page with MangoHud on and play for at least 30 seconds. When you close it, the session shows up here as \"Measured on this PC\".")),

            S("bottleneck", "games", "Bottleneck detector",
                "Finds out what is limiting your FPS: GPU, CPU, memory or temperature.",
                [
                    "Keep the page open: the verdict and the live gauges update by themselves.",
                    "For a better answer, click Start analysis, play for a few minutes and click Stop analysis.",
                    "Read the result: how long each part was the limit and tips on what to do.",
                ],
                Q("gargalo", "What is a bottleneck?", "It's the part that holds back the others' performance. If the GPU is always maxed out and the CPU has room to spare, the GPU is the bottleneck, and vice versa."),
                Q("fpsneeded", "Do I need to open the game through Ilmenyx?", "For the gauges, no. For FPS to enter the analysis, the game must have been opened with MangoHud (Games page).")),

            S("bench", "perf", "Benchmark",
                "Measures CPU, memory, GameSim (a game simulation), GPU, ray tracing and disk performance, and keeps the history on this PC.",
                [
                    "Choose the test.",
                    "Click Start and read the confirmation: it says how much load, memory or space the test will use.",
                    "Wait for it to finish (you can cancel at any time).",
                    "The result goes to the local history and to the PERFORMANCE card on the Overview.",
                ],
                Q("safe", "Is the benchmark safe?", "Yes. Nothing starts without your confirmation, there's a temperature limit and the disk test only uses a temporary file, deleted at the end."),
                Q("windows", "Can I compare the score with Windows?", "No. Ilmenyx's scores are experimental and not comparable to Windows ones."),
                Q("vary", "Why did the result change from one run to another?", "Background programs, temperature or power limit get in the way. Close other programs and run again before comparing.")),

            S("oc", "perf", "OC",
                "Helps with overclocking without touching the hardware: stability checker, NVIDIA GPU tuning through commands and a BIOS guide.",
                [
                    "To see whether the PC is stable, choose the duration and click Start check (with confirmation).",
                    "The check measures the score, applies load and checks the kernel log; it stops at the first error or at the temperature limit.",
                    "In GPU (NVIDIA with the official driver only), Generate commands creates the tuning commands for you to run in the terminal; Restore commands undoes them.",
                    "Read the BIOS guide if you want to overclock there.",
                ],
                Q("auto", "Does Ilmenyx overclock by itself?", "No. It never changes hardware or BIOS; it only generates commands you decide to run."),
                Q("what", "What is overclocking?", "It's making a part run above its factory speed. It gains performance, but it runs hotter and can cause crashes; that's why the stability checker exists.")),

            S("overlay", "perf", "Overlay",
                "Shows metrics such as FPS, CPU, GPU and temperature on top of the screen.",
                [
                    "Choose the items, the corner and the size.",
                    "Show overlay opens a small Ilmenyx window with the system's metrics.",
                    "To see it inside the game, check MangoHud in the game's profile (Games page): the configuration is created by itself. What you change here is saved automatically (\"Saved\" shows up) and also applies to MangoHud.",
                    "If you open the game directly from Steam, copy the launch option line shown on this page.",
                ],
                Q("fullscreen", "Why doesn't the overlay stay on top of a fullscreen game?", "That depends on the window manager (on Wayland, the compositor decides). Inside the game, use MangoHud."),
                Q("nofps", "Why doesn't FPS show in the overlay?", "FPS only exists for games started with MangoHud and Ilmenyx's configuration: check MangoHud in the game's profile on the Games page, or copy this page's launch option into Steam.")),

            S("validate", "perf", "Reduced validations",
                "Short tests that check whether the CPU, memory and GameSim calculations give the expected result. They don't measure performance or health.",
                [
                    "Choose CPU, Memory or GameSim and click to run.",
                    "Wait a few seconds for the result.",
                    "Export as JSON or HTML if you need to send it to someone.",
                ],
                Q("diff", "What's the difference from the Benchmark?", "The validation only checks that the calculation is right, in a few seconds and with little load. The Benchmark measures speed.")),

            S("stress", "perf", "Stress test",
                "Puts the CPU, GPU and/or RAM at maximum load to see whether the PC can take it, with an automatic temperature cutoff.",
                [
                    "Check CPU, GPU and/or RAM.",
                    "Choose the duration (0 = no limit) and the temperature limit (50 to 105 °C).",
                    "Save your work, click Start and confirm.",
                    "Watch the temperature and the errors: the test stops by itself if it goes past the limit, or when you tell it to stop.",
                ],
                Q("safe", "Is it safe to run the stress test?", "Yes, with care: it only starts after your confirmation, stops by itself when the temperature passes the chosen limit and always leaves at least 1 GiB of RAM free. The PC may be slow during the test, so save your work first."),
                Q("why", "What is a stress test for?", "To see whether the PC can take heavy load without freezing, shutting down or overheating, for example after building the PC, replacing the thermal paste or overclocking.")),

            S("makerports", "maker", "Maker · Ports",
                "Lists the USB serial ports (Arduino, ESP32 and other boards) without opening any.",
                [
                    "Plug the board into USB.",
                    "Click Refresh to see the port (e.g. /dev/ttyUSB0) and the chip.",
                    "If your user doesn't have access to the port, the page shows the suggested command for you to run.",
                ],
                Q("open", "Why doesn't Ilmenyx open the port?", "Opening the port can reset boards such as Arduino and ESP. Ilmenyx only reads the system's information.")),

            S("makerdrv", "maker", "Maker · Serial drivers",
                "Shows whether the drivers for the most common USB-serial chips are loaded and takes you to each one's official page.",
                [
                    "Click Check to check the chips.",
                    "See the status of each chip family.",
                    "Use Open official page when you need the manufacturer's driver.",
                ]),

            S("optimize", "tools", "Optimize",
                "Gets the PC ready for gaming: closes programs that get in the way and turns on system tweaks, all without a password and reversible.",
                [
                    "In PROGRAMS TO CLOSE, check what you want to close (file indexers, sync clients…).",
                    "Click Optimize: the checked ones close as if you closed the window, nothing forced.",
                    "In SYSTEM TWEAKS FOR GAMES, turn on what you want, such as the Performance power profile or turning off mouse acceleration.",
                    "Restore originals sets each tweak back to what it was.",
                    "In COMPRESSED MEMORY (ZRAM), PCs with up to 16 GB can turn ZRAM on through the distribution's official path (asks for the system password); Undo removes what Ilmenyx created.",
                ],
                Q("undo", "Can Optimize be undone?", "Yes. Ilmenyx keeps the original value of each tweak and Restore originals puts everything back. The closed programs can be opened again normally."),
                Q("root", "Does Optimize need a password?", "Only ZRAM. Closing programs and the tweaks in the list are your own user's; ZRAM installs a package and writes a system file, so the system asks for your password after you confirm."),
                Q("zram", "What is ZRAM and when is it worth it?", "It's a compressed swap area inside the RAM itself. With up to 16 GB, it helps when a game plus an open browser fill the memory and the PC freezes. Ilmenyx uses zram-generator (Fedora, Arch, openSUSE) or zram-tools (Ubuntu, Mint, Debian), doesn't touch anything if there's already ZRAM or another configuration, and Undo removes only what it created."),
                Q("shadercache", "What does \"Larger shader cache\" do?", "Video drivers keep on disk the shaders the game has already compiled, so it doesn't stutter again. Mesa's default limit (AMD and Intel) is 1 GB; new games fill that up and the cache is wiped. The option writes the file ~/.config/environment.d/90-ilmenyx-shader-cache.conf with a 10 GB limit for Mesa and NVIDIA. It takes effect from the next login and already in games opened by Ilmenyx; it uses more disk only as games need it. It doesn't change the video driver. Turning the option off deletes the file.")),

            S("lighting", "tools", "Integration",
                "Controls the RGB lights of the motherboard, memory, fans, keyboards and mice through OpenRGB, which ships with Ilmenyx.",
                [
                    "Click Start OpenRGB server (or use your own OpenRGB with the server on).",
                    "Click Connect to OpenRGB to list the devices.",
                    "Choose the color, the effect and the speed, check the devices and click Take control (with confirmation).",
                    "Restore original, or closing the app, puts each device back in the mode it was in.",
                ],
                Q("local", "Does OpenRGB access the internet?", "No. The server started by Ilmenyx only accepts connections from the PC itself (127.0.0.1) and is closed when you exit the app.")),

            S("startup", "tools", "Startup",
                "Lists the programs that open with your session, split into \"System (desktop)\" and \"Programs you installed\", with a sentence about what each one does and a recommendation.",
                [
                    "Click Refresh to see the list.",
                    "Read each item's recommendation: \"Required — don't turn off\", \"You can turn it off if you don't use…\", \"User\" or \"Unknown: look it up before turning it off\".",
                    "Turn off a program's switch so it no longer opens with the session (you can turn it back on). For system items, Ilmenyx shows a warning first.",
                    "Remove takes one of your programs off the list; Restore removed brings it back.",
                ],
                Q("uninstall", "Does removing it from startup uninstall the program?", "No. The program stays installed; it just stops opening by itself. The change takes effect the next time the session starts."),
                Q("system", "How does Ilmenyx know what belongs to the system?", "From a table of the components of the most common desktops (Cinnamon, GNOME, KDE Plasma, XFCE, MATE, LXQt, Budgie) and of the distribution, from the file's own markers (startup phase, \"only in\" a desktop) and, when possible, from the package that installed the file. What it doesn't recognize shows up as \"Unknown\".")),

            S("apps", "tools", "Install apps",
                "Installs the essential applications in one go after installing the system, from Flathub, only for your user and without a password.",
                [
                    "If asked, click Add Flathub.",
                    "Check the apps you want (Select all and Clear selection help).",
                    "Click Install selected; Stop interrupts it.",
                ],
                Q("flatpak", "What are Flatpak and Flathub?", "Flatpak is a way of installing apps that works on any Linux distribution; Flathub is the main store for these apps. If Flatpak isn't installed, Ilmenyx shows the command for your distribution."),
                Q("gaming", "Which gaming apps are on the list?", "In Games: Lutris, Heroic, ProtonUp-Qt, ProtonPlus (Proton versions), LACT (graphics card fan, power and overclock) and the Gamescope layer for the Flatpak Steam. In Streaming: Sunshine and GeForce NOW. In Peripherals: Piper (gaming mice), Solaar (Logitech) and input-remapper. None comes checked. The ones that need something extra on the system (a service such as lactd or ratbagd, or a udev rule) explain it before installing. GeForce NOW and input-remapper aren't on Flathub: Ilmenyx only opens the official page."),
                Q("gamescopelayer", "Why does the Gamescope layer require the Flatpak Steam?", "It's an extension of the Flatpak Steam and must match its base (runtime) version; Ilmenyx finds out that version and installs the right one. With the distribution's Steam, install the gamescope package from the system."),
                Q("rar", "How do I open .rar files without WinRAR?", "WinRAR has no Linux version. Check PeaZip on the list: it opens and extracts .rar, .zip and .7z files.")),

            S("driver", "tools", "Drivers",
                "Shows, by part type (video, network and Wi-Fi, Bluetooth, audio, printers and others), whether each one has a working driver and what to do when it doesn't. A driver is the program that lets Linux talk to the part. This page doesn't install anything.",
                [
                    "Click Check all and read the summary at the top: it says what's fine and what needs attention.",
                    "On each card, the label shows the part's status; when there's something to do, a single button appears (for example, Open the NVIDIA Driver tab).",
                    "\"Technical details\" shows the kernel module, the part's ID, the version and, for the graphics card, the version check (internet only when you click) and the suggested command.",
                    "Look for firmware updates shows whether fwupd has new firmware for your parts.",
                ],
                Q("amd", "Do I need to install a driver for Intel or AMD?", "Usually not: on Linux, their driver already comes with your distribution's kernel and Mesa."),
                Q("free", "What are open-source and proprietary drivers?", "Open source is open code and already comes with Linux. Proprietary is made by the manufacturer, with closed code, like NVIDIA's official driver. Both can work well."),
                Q("nodriver", "A part shows \"no driver\". Is that a problem?", "For video, network, Bluetooth and audio, yes: the part probably doesn't work. For internal motherboard parts it's usually normal, because Linux doesn't need them.")),

            S("nvdriver", "tools", "NVIDIA Driver",
                "Installs, checks, repairs and updates the right NVIDIA driver for your card and your system.",
                [
                    "Click Check to analyze the card and the current driver.",
                    "See the suggested plan; Show the script shows exactly what will be done.",
                    "Confirm: the system asks for your password in its own window.",
                    "When asked, restart the PC (How to restart explains) and open this page again to check.",
                ],
                Q("safe", "Does this page change anything without me asking?", "No. Everything is simulated first and nothing changes without your click and the system password. Ilmenyx also doesn't restart the PC by itself.")),

            S("report", "tools", "Report",
                "Gathers into a single file everything Ilmenyx reads from the machine, to keep or send to a technician.",
                [
                    "Click Export HTML (to read) or Export JSON (for programs).",
                    "Choose where to save: the file is always new, it never overwrites another.",
                    "Review the file before sharing.",
                ],
                Q("personal", "Does the report contain personal data?", "Serial numbers, computer and user names, MAC and IP addresses and home folder paths are removed. Even so, review it before sharing.")),

            S("blocked", "tools", "Blocked (!)",
                "Lists the features that aren't finished or tested yet and explains why. What doesn't exist on Linux (such as Windows tweaks) doesn't show up here.",
                [
                    "Click (!) next to an item to see the reason.",
                    "If the menu shows \"to test\", this PC has what's needed to test some blocked item.",
                ]),

            S("tools", "tools", "Requirements and about",
                "Checks the system requirements, shows licenses and credits and keeps some preferences.",
                [
                    "Requirements checks whether the system has what Ilmenyx needs.",
                    "Licenses and credits shows the project's version, licenses and credits.",
                    "Classic diagnostics panel opens the old diagnostics window.",
                    "In Preferences, turn the alerts on or off: USB stick or device, notification area, hot CPU and new version.",
                ],
                Q("tray", "How do I keep Ilmenyx in the notification area?", "Check \"When minimized, go to the notification area\" in Preferences. When you minimize, the window disappears and an icon stays near the clock; click it to come back or use its menu to pause the readings or quit. GNOME needs the AppIndicator extension; without a notification area, the window just minimizes."),
                Q("tempalert", "Will the hot CPU alert go off all the time?", "No. One-second spikes to 70–80 °C are normal when the processor boosts. The alert only appears if the CPU stays above the chosen limit for 20 seconds in a row, and then it waits 10 minutes and for the CPU to cool down before alerting again."),
                Q("updates", "How does Ilmenyx know a new version is out?", "If you allow it, it checks the project's releases page on GitHub once a day. No data from your PC is sent. When there's a new version, a notification arrives and the version in the corner of the sidebar becomes a link to the download page.")),
        ],
        [
            new("overview", "dash", ["dash"], "Overview",
                "This is the first screen: a live summary of your PC. The big card shows CPU, GPU and RAM right now, and the chart shows the activity of the last few minutes. A \"—\" means the reading doesn't exist on this PC, not that something is wrong."),
            new("sensors", "dash", ["sensorfix"], "Unlock sensors",
                "If the yellow \"Unlock CPU sensors\" button shows up here in the menu, click it to see the CPU temperature and power. The system asks for your password once (Ilmenyx never sees it), and you can undo it later."),
            new("diag", "system", ["system", "sensors", "gpu", "disks", "energy", "net", "procs"], "Diagnostics",
                "Here are the PC's details: System (the parts), Sensors, GPU, Disks (health), Power (battery), Network (lag test) and Processes (what's using the CPU). These pages only read: nothing is changed."),
            new("games", "launcher", ["launcher"], "Games",
                "Games from Steam, Heroic and Lutris show up by themselves; + Add executable adds another one, even a Windows .exe (runs with Proton), and Install Windows game runs a game's installer. In each game's profile you can turn on dedicated GPU, MangoHud (FPS on screen) and GameMode."),
            new("compat", "compat", ["compat", "gamecheck"], "Compatibility and Game won't open?",
                "Before playing, Compatibility shows whether the game runs well on Linux: ProtonDB rating, Steam Deck badge and anti-cheat. If Steam, Proton or a Flatpak won't open, Game won't open? checks the common causes without changing anything and shows the command for each fix."),
            new("fps", "fps", ["fps", "bottleneck"], "FPS estimate and bottleneck",
