            new("perf", "bench", ["bench", "oc", "validate", "stress"], "Benchmark, OC, validations and stress",
                "Benchmark measures performance, OC checks stability and Stress test puts the PC under maximum load. Reduced validations are short tests that only check whether the calculations give the expected result. No test starts without your confirmation, and they stop by themselves if the temperature passes the limit."),
            new("overlay", "overlay", ["overlay"], "Overlay",
